{
  "context": "loansimulation",
  "base_package": "com.bank.loans",
  "entities": [
    {
      "name": "Simulation",
      "table": "simulation",
      "key": ["numeroCorrelativo"],
      "fields": [
        {"name": "numeroCorrelativo", "type": "integer(32,signed)", "column": "numero_correlativo"},
        {"name": "monto", "type": "decimal(12,2,signed)", "column": "monto"},
        {"name": "plazo", "type": "integer(32,signed)", "column": "plazo"},
        {"name": "tasaAnual", "type": "decimal(5,2,signed)", "column": "tasa_anual"},
        {"name": "cuotaMensual", "type": "decimal(12,2,signed)", "column": "cuota_mensual"},
        {"name": "totalAPagar", "type": "decimal(14,2,signed)", "column": "total_a_pagar"},
        {"name": "fechaHora", "type": "timestamp(local)", "column": "fecha_hora"}
      ]
    }
  ],
  "ports": [
    {
      "name": "SimulationRepository",
      "entity": "Simulation",
      "methods": [
        {
          "name": "save",
          "description": "Persists an accepted simulation. The correlative number is generated by the database (sequence or identity column) and returned.",
          "inputs": [
            {"name": "monto", "type": "decimal(12,2,signed)"},
            {"name": "plazo", "type": "integer(32,signed)"},
            {"name": "tasaAnual", "type": "decimal(5,2,signed)"},
            {"name": "cuotaMensual", "type": "decimal(12,2,signed)"},
            {"name": "totalAPagar", "type": "decimal(14,2,signed)"},
            {"name": "fechaHora", "type": "timestamp(local)"}
          ],
          "returns": "int"
        }
      ]
    }
  ],
  "use_cases": [
    {
      "name": "SimulateConsumerLoan",
      "description": "Validates the amount (1000.00 to 50000.00) and the term (6 to 60 whole months), determines the annual rate from the term bracket, calculates the monthly installment with the French system (rounded to 2 decimals, half up) and the total to pay (installment x term). It then saves the accepted simulation for audit with a correlative number and timestamp. A rejected simulation is never saved. Called by the Simulador screen action 'calcular'; the result is shown on the Resultado screen.",
      "rules": ["RULE-001", "RULE-002", "RULE-003", "RULE-004", "RULE-005", "RULE-006"],
      "inputs": ["monto", "plazo"],
      "outputs": ["tasaAnual", "cuotaMensual", "totalAPagar"],
      "errors": [
        {"code": "AMOUNT_OUT_OF_RANGE", "message": "El monto debe estar entre 1.000 y 50.000"},
        {"code": "TERM_OUT_OF_RANGE", "message": "El plazo debe estar entre 6 y 60 meses"}
      ],
      "ports": ["SimulationRepository"],
      "http_method": "POST",
      "path": "/simulations"
    }
  ],
  "decisions": [
    {
      "title": "One operation for the whole simulation",
      "context": "The Simulador screen has a single action (calcular) that leads to Resultado. Rules 001 to 006 form one flow: validate, rate, installment, total, save.",
      "decision": "A single use case SimulateConsumerLoan exposed as POST /simulations covers all six rules. Validation runs first (amount, then term). If both are invalid, only the amount error is reported. Errors are returned as HTTP 422 with the stable code and the exact message from the specification. A non-integer or missing term or amount is a malformed request (HTTP 400) before the use case runs.",
      "consequences": "The client makes one call per simulation. Pure calculation (rate, installment, total) stays in the domain without dependencies, so it is easy to unit test."
    },
    {
      "title": "Rate bracket by term",
      "context": "RULE-003 defines three brackets.",
      "decision": "Term up to 12 months gives 12.00; 13 to 36 gives 14.50; 37 to 60 gives 16.00. Validation guarantees the term is between 6 and 60 before the rate is looked up. The brackets are domain constants, not data in a table.",
      "consequences": "Changing a bracket requires a code change and a new approval. There is no rate table to maintain."
    },
    {
      "title": "Decimal arithmetic and rounding",
      "context": "Installment = M x i / (1 - (1+i)^-n) with i = annual rate / 100 / 12. The approved scenarios require exact cents (888.49, 241.25, 10661.88).",
      "decision": "Use BigDecimal only, never floating point. The monthly rate and the power (1+i)^-n are computed with MathContext.DECIMAL128 (integer exponent, so no double conversion). Only the final installment is rounded, to 2 decimals with RoundingMode.HALF_UP. The total is the already rounded installment multiplied by the term, kept at 2 decimals (no further rounding needed). The total is not recomputed from the unrounded installment.",
      "consequences": "Results are deterministic and match the acceptance criteria. Intermediate precision is not persisted."
    },
    {
      "title": "Only accepted simulations are persisted, in one transaction",
      "context": "RULE-006 requires saving every accepted simulation with a correlative number, amount, term, rate, installment, total and date-time, and saving nothing when it is rejected.",
      "decision": "Validation happens before any call to SimulationRepository, so a rejected simulation never touches the database. The save is one write in a transaction on the use case. If the write fails, the whole operation fails and no result is returned. The correlative number is generated by the database (sequence or identity) on column numero_correlativo, which is the key. The timestamp comes from an injected Clock in local time and is set by the use case.",
      "consequences": "There is no gap logic or application-side counter. Correlative numbers may skip values after failed transactions, which is acceptable for audit. The number and date-time are stored but not returned by the operation, because the Resultado screen does not show them."
    }
  ],
  "infrastructure": [],
  "masks": []
}
